{"path":"about.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfaf8;--ink:#1f2326;--muted:#6b6f73;--accent:#8aa29b;--card:#ffffff}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial; color:var(--ink);background:var(--bg);}
    .site{max-width:980px;margin:36px auto;padding:28px}
    header{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-weight:600}
    .hero{background:linear-gradient(180deg,rgba(138,162,155,0.06),transparent);padding:32px;border-radius:12px;position:relative;overflow:hidden}
    .hero svg{position:absolute;right:-40px;top:-40px;opacity:.12;width:220px;height:220px}
    h1{margin:0 0 8px;font-size:28px;letter-spacing:-0.4px}
    p.lead{margin:0;color:var(--muted)}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:20px;margin-top:20px}
    .card{background:var(--card);padding:18px;border-radius:10px;box-shadow:0 6px 18px rgba(20,22,23,0.06)}
    .diagnostic .options{display:flex;flex-direction:column;gap:8px;margin-top:12px}
    .mood{display:flex;align-items:center;gap:10px;padding:10px;border-radius:8px;border:1px solid #e8e9ea;cursor:pointer}
    .mood input{display:none}
    .mood.selected{background:linear-gradient(90deg,rgba(138,162,155,0.12),transparent);border-color:rgba(138,162,155,0.2)}
    .method{margin-top:12px}
    .cta{display:inline-block;margin-top:14px;padding:10px 14px;border-radius:8px;background:var(--accent);color:white;text-decoration:none;font-weight:700}
    .micro{display:flex;flex-direction:column;gap:10px;margin-top:14px}
    footer{margin-top:28px;color:var(--muted);font-size:13px}
    @media(max-width:880px){.grid{grid-template-columns:1fr;}.hero svg{display:none}}
  </style>
</head>
<body>
  <div class='site'>
    <header>
      <div><strong>{{BUSINESS_NAME}}</strong></div>
      <nav>
        <a href='index.html'>Practice</a>
        <a href='services.html'>Offerings</a>
        <a href='programs.html'>Journeys</a>
        <a href='contact.html'>Reach</a>
      </nav>
    </header>

    <section class='hero card'>
      <svg viewBox='0 0 100 100' xmlns='http://www.w3.org/2000/svg' aria-hidden='true'>
        <defs><linearGradient id='g' x1='0' x2='1'><stop offset='0' stop-color='#8aa29b'/><stop offset='1' stop-color='#cfe1da'/></linearGradient></defs>
        <circle cx='40' cy='30' r='32' fill='url(#g)' />
        <g fill='white' opacity='0.6'><path d='M20 70c6-10 28-8 36-2s22 4 24 0c-18 2-40-6-60 2z'/></g>
      </svg>
      <h1>About the work</h1>
      <p class='lead'>Small changes, ruled by what you actually do. I design frameworks that hold through busy days, with clear habits and steady outcomes.</p>
    </section>

    <div class='grid'>
      <div>
        <section class='card diagnostic'>
          <h3>How do you feel right now?</h3>
          <p class='lead'>Choose one and see the immediate approach I recommend.</p>
          <div id='moodOptions' class='options'>
            <label class='mood' data-title='Ease & Focus' data-desc='Short, 15–25 minute practices: brief resets, single-focus rhythms, and a tidy end-of-day close.' data-cta='Schedule a Short Reset'>
              <input type='radio' name='mood' value='ease'>
              <div>
                <strong>Rushed</strong>
                <div style='font-size:13px;color:var(--muted)'>Seconds to spare; need a quick anchor</div>
              </div>
            </label>

            <label class='mood' data-title='Slow Rebuild' data-desc='Modulated routines across the week: simple rituals, habit pairings, and an easy tracking rhythm.' data-cta='Begin a Slow Rebuild'>
              <input type='radio' name='mood' value='rebuild'>
              <div>
                <strong>Worn out</strong>
                <div style='font-size:13px;color:var(--muted)'>Low bandwidth; want structure that doesn\'t exhaust</div>
              </div>
            </label>

            <label class='mood' data-title='Clarity Sprint' data-desc='Focused attention blocks with reflective prompts—two to four weeks of tightened habits to recalibrate momentum.' data-cta='Start a Clarity Sprint'>
              <input type='radio' name='mood' value='clarity'>
              <div>
                <strong>Foggy</strong>
                <div style='font-size:13px;color:var(--muted)'>Need a directional nudge and clear metrics</div>
              </div>
            </label>
          </div>

          <div class='method'>
            <h4 id='methodTitle'>A small method for your day</h4>
            <p id='methodDesc' style='color:var(--muted)'>Select a state to reveal a tailored approach and a next step.</p>
            <a id='moodCta' class='cta' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </section>

        <section class='card' style='margin-top:16px'>
          <h3>Short map, lasting habits</h3>
          <p class='lead'>Plans are built from three elements: a clear outcome, a few repeatable cues, and micro-habits that stick.</p>
          <div class='micro'>
            <div><strong>Outcome</strong><div style='color:var(--muted)'>One measurable shift to track for the first 30 days.</div></div>
            <div><strong>Cues</strong><div style='color:var(--muted)'>Two reliable signals you can attach practice to—times of day or existing routines.</div></div>
            <div><strong>Micro-habits</strong><div style='color:var(--muted)'>Tiny actions, repeated. Progress is the sum of small, chosen acts.</div></div>
          </div>
        </section>
      </div>

      <aside>
        <section class='card'>
          <h4>What I offer</h4>
          <p style='color:var(--muted)'>Blended support: live coaching, guided blueprints, and short intensives. No medical advice — just practical frameworks.</p>
          <div style='margin-top:12px'>
            <div style='font-weight:700'>{{CITY}}, {{STATE}}</div>
            <div style='color:var(--muted);font-size:14px;margin-top:8px'>Contact: <a href='tel:{{PHONE}}' style='color:inherit;text-decoration:none'>{{PHONE}}</a></div>
          </div>
        </section>

        <section class='card' style='margin-top:12px'>
          <h4>First step</h4>
          <p style='color:var(--muted)'>A 20-minute discovery call to shape a proposal from what you already do.</p>
          <a class='cta' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
        </section>
      </aside>
    </div>

    <footer>
      <div>Questions? <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></div>
    </footer>
  </div>

  <script>
    (function(){
      const options = document.querySelectorAll('#moodOptions .mood');
      const title = document.getElementById('methodTitle');
      const desc = document.getElementById('methodDesc');
      const cta = document.getElementById('moodCta');

      options.forEach(opt => {
        opt.addEventListener('click', ()=>{
          options.forEach(o=>o.classList.remove('selected'));
          opt.classList.add('selected');
          title.textContent = opt.getAttribute('data-title');
          desc.textContent = opt.getAttribute('data-desc');
          cta.textContent = opt.getAttribute('data-cta');
          cta.href = '{{PRIMARY_CTA_URL}}';
        });
      });
    })();
  </script>
</body>
</html>"} 
{"path":"services.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffaf8;--ink:#1e2224;--muted:#6d7174;--accent:#b57e61;--card:#ffffff}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto;background:var(--bg);color:var(--ink)}
    .wrap{max-width:980px;margin:36px auto;padding:22px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none;font-weight:600}
    .intro{display:flex;gap:18px;align-items:center;margin-top:18px}
    .intro .text{flex:1}
    .controls{display:flex;gap:12px;align-items:center}
    .switch{display:inline-flex;align-items:center;padding:6px 8px;border-radius:999px;background:#fff;border:1px solid #eee}
    .services{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}
    .card{padding:16px;border-radius:12px;background:var(--card);box-shadow:0 8px 20px rgba(30,34,36,0.05)}
    h2{margin:0 0 6px}
    .price{font-size:20px;font-weight:800;color:var(--accent)}
    .meta{color:var(--muted);font-size:13px}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:8px;background:var(--accent);color:white;text-decoration:none;font-weight:700}
    @media(max-width:900px){.services{grid-template-columns:1fr;}.intro{flex-direction:column;align-items:flex-start}}
  </style>
</head>
<body>
  <div class='wrap'>
    <header>
      <div><strong>{{BUSINESS_NAME}}</strong></div>
      <nav>
        <a href='index.html'>Practice</a>
        <a href='about.html'>About</a>
        <a href='programs.html'>Journeys</a>
        <a href='contact.html'>Reach</a>
      </nav>
    </header>

    <section class='intro'>
      <div class='text'>
        <h1>Offerings & structures</h1>
        <p style='color:var(--muted)'>Blended supports: single sessions, multi-week intensives, and packaged blueprints that scale with your life.</p>
      </div>

      <div class='controls card'>
        <div style='font-size:13px;color:var(--muted);margin-bottom:8px'>Pricing view</div>
        <div class='switch'>
          <label style='font-size:13px;color:var(--muted);margin-right:8px'>Monthly</label>
          <input id='priceToggle' type='checkbox' aria-label='Toggle pricing view'>
          <label style='font-size:13px;color:var(--muted);margin-left:8px'>Package</label>
        </div>
      </div>
    </section>

    <section class='services'>
      <div class='card'>
        <h2>Pulse Session</h2>
        <div class='meta'>A focused 45-minute session for quick recalibration.</div>
        <div class='price' data-monthly='95' data-package='360'>$<span class='num'>95</span></div>
        <div style='color:var(--muted);font-size:13px;margin-top:8px'>Single booking or part of a package</div>
        <a class='cta' href='{{PRIMARY_CTA_URL}}'>Book a Pulse</a>
      </div>

      <div class='card'>
        <h2>Blueprint Package</h2>
        <div class='meta'>A 6-week blueprint: habits, checkpoints, and two coaching calls.</div>
        <div class='price' data-monthly='220' data-package='1200'>$<span class='num'>220</span></div>
        <div style='color:var(--muted);font-size:13px;margin-top:8px'>Week-by-week check-ins and a living plan</div>
        <a class='cta' href='{{PRIMARY_CTA_URL}}'>Claim a Blueprint</a>
      </div>

      <div class='card'>
        <h2>Seasonal Reset</h2>
        <div class='meta'>Short intensive to shift routine and reset momentum (2–3 weeks).</div>
        <div class='price' data-monthly='140' data-package='540'>$<span class='num'>140</span></div>
        <div style='color:var(--muted);font-size:13px;margin-top:8px'>Focused tools and daily micro-actions</div>
        <a class='cta' href='{{PRIMARY_CTA_URL}}'>Start a Reset</a>
      </div>
    </section>

    <footer style='margin-top:22px;color:var(--muted)'>
      <div>Questions? <a href='mailto:{{EMAIL}}' style='color:inherit;text-decoration:none'>{{EMAIL}}</a></div>
    </footer>
  </div>

  <script>
    // Pricing comparator with animated numbers
    (function(){
      const toggle = document.getElementById('priceToggle');
      const prices = Array.from(document.querySelectorAll('.price'));

      function animateNumber(el, start, end, duration){
        const span = el.querySelector('.num');
        const startTime = performance.now();
        function frame(now){
          const t = Math.min(1,(now-startTime)/duration);
          const value = Math.round(start + (end-start)*t);
          span.textContent = value;
          if(t<1) requestAnimationFrame(frame);
        }
        requestAnimationFrame(frame);
      }

      function update(toPackage){
        prices.forEach(p=>{
          const monthly = parseInt(p.getAttribute('data-monthly'),10);
          const pack = parseInt(p.getAttribute('data-package'),10);
          const current = parseInt(p.querySelector('.num').textContent,10)||monthly;
          const target = toPackage?pack:monthly;
          animateNumber(p,current,target,420);
        });
      }

      toggle.addEventListener('change',()=>{
        update(toggle.checked);
      });
    })();
  </script>
</body>
</html>"} 
{"path":"programs.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Journeys — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7fbfb;--ink:#122023;--muted:#516366;--accent:#4a7c74;--card:#ffffff}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto;background:var(--bg);color:var(--ink)}
    .container{max-width:980px;margin:36px auto;padding:20px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    .hero{padding:18px;background:linear-gradient(180deg,rgba(74,124,116,0.06),transparent);border-radius:10px}
    .programs{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .list{display:flex;flex-direction:column;gap:12px}
    .prog{background:var(--card);padding:14px;border-radius:10px;box-shadow:0 10px 22px rgba(18,32,35,0.04)}
    .prog h3{margin:0}
    .meta{color:var(--muted);font-size:13px}
    .selector{display:flex;gap:8px;margin-top:10px}
    .mood{padding:10px;border-radius:8px;border:1px solid #eef3f3;cursor:pointer}
    .mood.selected{background:linear-gradient(90deg,rgba(74,124,116,0.12),transparent);border-color:rgba(74,124,116,0.18)}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:8px;background:var(--accent);color:white;text-decoration:none;font-weight:700}
    @media(max-width:900px){.programs{grid-template-columns:1fr;}}
  </style>
</head>
<body>
  <div class='container'>
    <header>
      <div><strong>{{BUSINESS_NAME}}</strong></div>
      <nav>
        <a href='index.html'>Practice</a>
        <a href='about.html'>About</a>
        <a href='services.html'>Offerings</a>
        <a href='contact.html'>Reach</a>
      </nav>
    </header>

    <section class='hero'>
      <h1>Programs shaped to living life</h1>
      <p style='color:var(--muted)'>Programs are named for the change they shepherd—each is a compact architecture of habits and checkpoints.</p>
    </section>

    <div class='programs'>
      <div class='list'>
        <div class='prog'>
          <h3>Alignment Course</h3>
          <div class='meta'>10 weeks of pacing, tools, and measurable checkpoints for steadier days.</div>
          <div style='margin-top:10px'>
            <strong>Includes:</strong>
            <ul style='margin:6px 0 0 18px;color:var(--muted)'>
              <li>Weekly coaching</li>
              <li>Custom habit map</li>
              <li>Mid-course review</li>
            </ul>
          </div>
        </div>

        <div class='prog'>
          <h3>Momentum Mini</h3>
          <div class='meta'>Six focused weeks—pairing a single outcome with daily micro-habits.</div>
          <div style='margin-top:10px'>
            <strong>Includes:</strong>
            <ul style='margin:6px 0 0 18px;color:var(--muted)'>
              <li>Bi-weekly check-ins</li>
              <li>Daily micro-prompts</li>
            </ul>
          </div>
        </div>
      </div>

      <aside>
        <section class='card prog' style='padding:14px'>
          <h4>Choose how you feel</h4>
          <p style='color:var(--muted)'>Select a current state to reveal the program rhythm I suggest and a tailored next step.</p>

          <div class='selector' id='moodPane'>
            <div class='mood' data-title='Anchor & Shorten' data-desc='Daily 10-minute anchors and a weekly check to shore up constant pressure.' data-cta='Join a Momentum Mini'>Busy</div>
            <div class='mood' data-title='Pace & Build' data-desc='Stretch across six to ten weeks: gentle increases, paired cues, and an easy tracking habit.' data-cta='Start an Alignment Course'>Depleted</div>
            <div class='mood' data-title='Tidy Reset' data-desc='A tight 2–3 week reset—clear practices and defined endpoints to regain clarity.' data-cta='Begin a Tidy Reset'>Unfocused</div>
          </div>

          <div style='margin-top:12px'>
            <h4 id='progTitle'>Suggested path</h4>
            <p id='progDesc' style='color:var(--muted)'>Select a state to see the recommended program rhythm.</p>
            <a id='progCta' class='cta' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </section>

        <section class='prog' style='margin-top:12px'>
          <h4>Simple commitments</h4>
          <p style='color:var(--muted)'>Programs pair outcome-driven targets with three repeatable cues. They are coaching plus a living plan.</p>
          <div style='margin-top:8px'><a class='cta' href='{{PRIMARY_CTA_URL}}'>Talk about a program</a></div>
        </section>
      </aside>
    </div>

    <footer style='margin-top:20px;color:var(--muted)'>
      <div>Reach out at <a href='mailto:{{EMAIL}}' style='color:inherit;text-decoration:none'>{{EMAIL}}</a></div>
    </footer>
  </div>

  <script>
    // Mood-to-Method selector (programs)
    (function(){
      const items = document.querySelectorAll('#moodPane .mood');
      const title = document.getElementById('progTitle');
      const desc = document.getElementById('progDesc');
      const cta = document.getElementById('progCta');

      items.forEach(it => {
        it.addEventListener('click', ()=>{
          items.forEach(i=>i.classList.remove('selected'));
          it.classList.add('selected');
          title.textContent = it.getAttribute('data-title');
          desc.textContent = it.getAttribute('data-desc');
          cta.textContent = it.getAttribute('data-cta');
          cta.href = '{{PRIMARY_CTA_URL}}';
        });
      });
    })();
  </script>
</body>
</html>"} 
